//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::atomic::{AtomicI64, Ordering};
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

/// Clones share the same scores, so each match thread keeps its own handle.
/// Scores live in atomics so no operation ever holds two locks at once:
/// holding one lock while taking the same mutex again deadlocked the server,
/// and read-then-write sequences under separate locks lost concurrent updates.
#[derive(Clone, Default)]
pub struct Board {
    players: Arc<Mutex<HashMap<PlayerId, Arc<AtomicI64>>>>,
    total: Arc<AtomicI64>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        let previous = self
            .players
            .lock()
            .unwrap()
            .insert(id, Arc::new(AtomicI64::new(score)));
        // Only the difference hits the total, so a player re-joining does not
        // inflate it while their old score is dropped.
        let delta = score - previous.map_or(0, |old| old.load(Ordering::Relaxed));
        self.total.fetch_add(delta, Ordering::Relaxed);
    }

    fn slot(&self, id: PlayerId) -> Arc<AtomicI64> {
        self.players.lock().unwrap()[&id].clone()
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        self.slot(id).fetch_add(points, Ordering::Relaxed);
        self.total.fetch_add(points, Ordering::Relaxed);
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        if from == to {
            return;
        }
        self.slot(from).fetch_sub(points, Ordering::Relaxed);
        self.slot(to).fetch_add(points, Ordering::Relaxed);
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        self.slot(id).load(Ordering::Relaxed)
    }

    pub fn total(&self) -> i64 {
        self.total.load(Ordering::Relaxed)
    }
}


