use arena_scores::Board;
use std::sync::Arc;
use std::thread;

#[test]
fn many_threads_keep_the_scores() {
    let board = Arc::new(Board::new());
    board.join(1, 0);
    board.join(2, 0);

    // A self-transfer must do nothing, not deadlock.
    board.transfer(1, 1, 5);

    let mut handles = Vec::new();
    for _ in 0..8 {
        let board = Arc::clone(&board);
        handles.push(thread::spawn(move || {
            for _ in 0..1000 {
                board.award(1, 1);
                board.transfer(1, 2, 1);
                board.transfer(2, 1, 1);
            }
        }));
    }
    for h in handles {
        h.join().unwrap();
    }

    assert_eq!(board.score(1), 8000);
    assert_eq!(board.score(2), 0);
    assert_eq!(board.total(), 8000);
}
